//! Day intelligence: from captured activity to hour reports, the day's
//! workstreams, and the day summary with its standup, generated by the
//! user's activity provider and delivered on schedule with notifications.
//! Contract, schema, and read API: `docs/day-intelligence.md`.
//!
//! Layout: `distill` + `embedder` (local text reduction, no network but the
//! one-time model download), `hour`, `workstreams`, `summary` (prompts in and
//! answers out, pure), `prompts`, `schedule` (time decisions, pure),
//! `notify` (notice queue and quiet hours), `sources` (meetings and notes,
//! coding-agent blocks), `db` (tables and read API), `pipeline`
//! (orchestration over injected dependencies), and this file (Tauri state,
//! background loop, commands).

pub mod db;
pub mod distill;
pub mod embedder;
pub mod hour;
pub mod notify;
pub mod pipeline;
pub mod prompts;
pub mod schedule;
pub mod sources;
pub mod summary;
pub mod workstreams;

